fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // Handle the empty array case
    if a.is_empty() {
        return (Vec::new(), Vec::new());
    }
    
    // Handle the single element case
    if a.len() == 1 {
        return (Vec::new(), a);
    }
    
    // Split the array into two parts
    let first_array = vec![a[0]]; // Take the first element
    let second_array = a[1..].to_vec(); // Take the rest of the elements
    
    (first_array, second_array)
}